package com.competitive.clan;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CompetitiveClanPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CompetitiveClanPlugin.class);
		RuneLite.main(args);
	}
}

package com.competitive.clan.services;

import static org.junit.Assert.assertEquals;
import org.junit.Test;
import com.competitive.clan.models.SystemMessageType;

public class ChatClassifierTest
{
	@Test
	public void classifiesDropBroadcast()
	{
		String message = "PlayerName received a drop: Twisted bow (1,181,724,847 coins)";
		assertEquals(SystemMessageType.DROP, ChatClassifier.classify(message));
	}

	@Test
	public void classifiesPetDrop()
	{
		String message = "PlayerName has a funny feeling like they're being followed";
		assertEquals(SystemMessageType.PET_DROP, ChatClassifier.classify(message));
	}

	@Test
	public void classifiesRaidDrop()
	{
		String message = "PlayerName received special loot from a raid: Ancestral hat";
		assertEquals(SystemMessageType.RAID_DROP, ChatClassifier.classify(message));
	}

	@Test
	public void unclassifiedMessagesAreUnknown()
	{
		assertEquals(SystemMessageType.UNKNOWN, ChatClassifier.classify("just some regular clan message"));
	}

	@Test
	public void sanitizeStripsJagexFormatting()
	{
		String raw = "Player\u00A0name found <img=1>an item<lt>tag<gt>";
		String cleaned = ChatClassifier.sanitize(raw);
		assertEquals("Player name found an item<tag>", cleaned);
	}
}

package com.competitive.clan.services;

import net.runelite.client.config.ConfigManager;

public final class RuneLiteSessionStore implements SessionStore
{
	private static final String CONFIG_GROUP = "competitiveClan";
	private static final String SESSION_TOKEN = "sessionToken";
	private static final String PENDING_VERIFICATION_ID = "pendingVerificationId";

	private final ConfigManager configManager;

	public RuneLiteSessionStore(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	@Override
	public String getSessionToken()
	{
		return value(SESSION_TOKEN);
	}

	@Override
	public void setSessionToken(String token)
	{
		setOrUnset(SESSION_TOKEN, token);
	}

	@Override
	public String getPendingVerificationId()
	{
		return value(PENDING_VERIFICATION_ID);
	}

	@Override
	public void setPendingVerificationId(String verificationId)
	{
		setOrUnset(PENDING_VERIFICATION_ID, verificationId);
	}

	@Override
	public void clear()
	{
		configManager.unsetConfiguration(CONFIG_GROUP, SESSION_TOKEN);
		configManager.unsetConfiguration(CONFIG_GROUP, PENDING_VERIFICATION_ID);
	}

	private String value(String key)
	{
		String value = configManager.getConfiguration(CONFIG_GROUP, key);
		return value == null ? "" : value;
	}

	private void setOrUnset(String key, String value)
	{
		if (value == null || value.isEmpty())
		{
			configManager.unsetConfiguration(CONFIG_GROUP, key);
		}
		else
		{
			configManager.setConfiguration(CONFIG_GROUP, key, value);
		}
	}
}

package com.competitive.clan.services;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;
import com.competitive.clan.models.ChatBridgeMessage;

/**
 * Two-way clan chat &lt;-&gt; Discord mirror over a websocket:
 *  - persistent connection with a keepalive ping and periodic reconnect check
 *  - outbound messages queued and flushed as a batch every ~2 seconds
 *  - a short-lived dedup cache so a message doesn't bounce game -> Discord -> game
 */
@Slf4j
public final class DefaultChatBridgeService implements ChatBridgeService
{
	private static final long FLUSH_INTERVAL_SECONDS = 2;
	private static final long RECONNECT_CHECK_SECONDS = 30;
	private static final long DEDUP_WINDOW_MILLIS = 3_000;
	private static final Type MESSAGE_LIST_TYPE = new TypeToken<List<ChatBridgeMessage>>() { }.getType();

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final String webSocketUrl;
	private final VerificationService verification;

	private final Queue<ChatBridgeMessage> outboundQueue = new ConcurrentLinkedQueue<>();
	private final List<Consumer<ChatBridgeMessage>> inboundListeners = new CopyOnWriteArrayList<>();
	private final RecentMessageCache dedupCache = new RecentMessageCache(DEDUP_WINDOW_MILLIS);

	private final ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor(runnable ->
	{
		Thread thread = new Thread(runnable, "competitive-clan-chat-bridge");
		thread.setDaemon(true);
		return thread;
	});

	private volatile WebSocket activeSocket;
	private volatile boolean shouldStayConnected = false;
	private ScheduledFuture<?> flushTask;
	private ScheduledFuture<?> reconnectTask;

	public DefaultChatBridgeService(OkHttpClient httpClient, Gson gson, String webSocketUrl, VerificationService verification)
	{
		// pingInterval gives us the "keepalive" behavior at the OkHttp layer without extra bookkeeping.
		this.httpClient = httpClient.newBuilder().pingInterval(10, TimeUnit.SECONDS).build();
		this.gson = gson;
		this.webSocketUrl = webSocketUrl;
		this.verification = verification;
	}

	@Override
	public synchronized void connect()
	{
		shouldStayConnected = true;
		openSocket();
		if (flushTask == null)
		{
			flushTask = scheduler.scheduleAtFixedRate(this::flushOutboundQueue, FLUSH_INTERVAL_SECONDS, FLUSH_INTERVAL_SECONDS, TimeUnit.SECONDS);
		}
		if (reconnectTask == null)
		{
			reconnectTask = scheduler.scheduleAtFixedRate(this::reconnectIfNeeded, RECONNECT_CHECK_SECONDS, RECONNECT_CHECK_SECONDS, TimeUnit.SECONDS);
		}
	}

	@Override
	public synchronized void disconnect()
	{
		shouldStayConnected = false;
		if (flushTask != null)
		{
			flushTask.cancel(false);
			flushTask = null;
		}
		if (reconnectTask != null)
		{
			reconnectTask.cancel(false);
			reconnectTask = null;
		}
		if (activeSocket != null)
		{
			activeSocket.close(1000, "Plugin shutting down");
			activeSocket = null;
		}
	}

	@Override
	public boolean isConnected()
	{
		return activeSocket != null;
	}

	@Override
	public void enqueueOutbound(ChatBridgeMessage message)
	{
		if (!verification.isVerified())
		{
			log.debug("Skipping outbound chat bridge message - client not verified");
			return;
		}
		if (dedupCache.seenRecently(message))
		{
			return;
		}
		dedupCache.remember(message);
		outboundQueue.add(message);
	}

	@Override
	public void onInboundMessage(Consumer<ChatBridgeMessage> listener)
	{
		inboundListeners.add(listener);
	}

	private void openSocket()
	{
		Request request = new Request.Builder().url(webSocketUrl)
			.header("Authorization", "Bearer " + verification.getSessionToken())
			.build();

		activeSocket = httpClient.newWebSocket(request, new WebSocketListener()
		{
			@Override
			public void onOpen(WebSocket webSocket, Response response)
			{
				log.info("Competitive clan chat bridge connected");
			}

			@Override
			public void onMessage(WebSocket webSocket, String text)
			{
				handleInboundPayload(text);
			}

			@Override
			public void onFailure(WebSocket webSocket, Throwable t, Response response)
			{
				log.debug("Chat bridge connection failed, will retry on next reconnect check: {}", t.getMessage());
				activeSocket = null;
			}

			@Override
			public void onClosed(WebSocket webSocket, int code, String reason)
			{
				log.debug("Chat bridge connection closed: {} {}", code, reason);
				activeSocket = null;
			}
		});
	}

	private void reconnectIfNeeded()
	{
		if (shouldStayConnected && activeSocket == null)
		{
			log.debug("Attempting to reconnect chat bridge");
			openSocket();
		}
	}

	private void flushOutboundQueue()
	{
		if (activeSocket == null || outboundQueue.isEmpty())
		{
			return;
		}
		List<ChatBridgeMessage> batch = new ArrayList<>();
		ChatBridgeMessage next;
		while ((next = outboundQueue.poll()) != null)
		{
			batch.add(next);
		}
		if (!batch.isEmpty())
		{
			activeSocket.send(gson.toJson(batch));
		}
	}

	private void handleInboundPayload(String text)
	{
		try
		{
			List<ChatBridgeMessage> messages = gson.fromJson(text, MESSAGE_LIST_TYPE);
			if (messages == null)
			{
				return;
			}
			for (ChatBridgeMessage message : messages)
			{
				// Inbound = Discord chat mirrored into the game, staff announcements, or bingo alerts.
				if (message.getOrigin() != ChatBridgeMessage.Origin.DISCORD
					&& message.getOrigin() != ChatBridgeMessage.Origin.ANNOUNCEMENT
					&& message.getOrigin() != ChatBridgeMessage.Origin.BINGO)
				{
					continue;
				}
				if (dedupCache.seenRecently(message))
				{
					continue;
				}
				dedupCache.remember(message);
				for (Consumer<ChatBridgeMessage> listener : inboundListeners)
				{
					listener.accept(message);
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to parse inbound chat bridge payload: {}", e.getMessage());
		}
	}

	/**
	 * Rolling, time-windowed dedup cache keyed on origin+author+content, so a message relayed
	 * game -> Discord doesn't bounce straight back into clan chat (or vice versa) as a duplicate.
	 */
	private static final class RecentMessageCache
	{
		private final long windowMillis;
		private final Queue<Entry> entries = new ConcurrentLinkedQueue<>();

		RecentMessageCache(long windowMillis)
		{
			this.windowMillis = windowMillis;
		}

		synchronized boolean seenRecently(ChatBridgeMessage message)
		{
			purgeExpired();
			String key = key(message);
			return entries.stream().anyMatch(entry -> entry.key.equals(key));
		}

		synchronized void remember(ChatBridgeMessage message)
		{
			purgeExpired();
			entries.add(new Entry(key(message), System.currentTimeMillis()));
		}

		private void purgeExpired()
		{
			long cutoff = System.currentTimeMillis() - windowMillis;
			entries.removeIf(entry -> entry.timestamp < cutoff);
		}

		private static String key(ChatBridgeMessage message)
		{
			return message.getOrigin() + "|" + message.getAuthor() + "|" + message.getContent();
		}

		private static final class Entry
		{
			final String key;
			final long timestamp;

			Entry(String key, long timestamp)
			{
				this.key = key;
				this.timestamp = timestamp;
			}
		}
	}
}

package com.competitive.clan.services;

import com.competitive.clan.models.SystemMessageType;

/**
 * Classifies and sanitizes clan chat broadcast text so the bot can decide which lines
 * become rich embeds (drops, raids, collection log, quests, diaries, level-ups) and which
 * are mirrored as plain text.
 */
public final class ChatClassifier
{
	private ChatClassifier()
	{
	}

	public static SystemMessageType classify(String message)
	{
		if (message.contains("received a drop:"))
		{
			return SystemMessageType.DROP;
		}
		else if (message.contains("received special loot from a raid:"))
		{
			return SystemMessageType.RAID_DROP;
		}
		else if (message.contains("has a funny feeling like"))
		{
			return SystemMessageType.PET_DROP;
		}
		else if (message.contains("received a new collection log item:"))
		{
			return SystemMessageType.COLLECTION_LOG;
		}
		else if (message.contains("personal best:"))
		{
			return SystemMessageType.PERSONAL_BEST;
		}
		else if (message.contains("has completed a clue scroll") || message.contains("received clue"))
		{
			return SystemMessageType.CLUE_DROP;
		}
		else if (message.contains("has completed a quest:"))
		{
			return SystemMessageType.QUEST;
		}
		else if (message.contains("has levelled up") || message.contains("has reached"))
		{
			return SystemMessageType.LEVEL_UP;
		}
		else if (message.contains("has completed a") && message.contains("combat task"))
		{
			return SystemMessageType.COMBAT_ACHIEVEMENT;
		}
		else if (message.contains("has completed") && message.contains("Achievement Diary"))
		{
			return SystemMessageType.DIARY;
		}
		else if (message.contains("has defeated") || message.contains("has been defeated by"))
		{
			return SystemMessageType.PVP_KILL;
		}
		else if (message.contains("has joined the clan") || message.contains("has left the clan")
			|| message.contains("has been promoted") || message.contains("has been demoted"))
		{
			return SystemMessageType.ATTENDANCE;
		}
		return SystemMessageType.UNKNOWN;
	}

	public static String sanitize(String message)
	{
		String cleaned = message;
		cleaned = cleaned.replace((char) 160, ' '); // Jagex's non-breaking space
		cleaned = cleaned.replace("<lt>", "<");
		cleaned = cleaned.replace("<gt>", ">");
		cleaned = stripImageTags(cleaned);
		cleaned = stripColorTags(cleaned);
		return cleaned;
	}

	private static String stripImageTags(String message)
	{
		return message.replaceAll("<img=\\d+>", "");
	}

	/** Removes Jagex colour markup (e.g. item names in drop broadcasts) so Discord shows clean text. */
	private static String stripColorTags(String message)
	{
		return message.replaceAll("<col=[^>]*>", "").replace("</col>", "");
	}
}

package com.competitive.clan.services;

import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import com.competitive.clan.api.ApiException;
import com.competitive.clan.api.ClanApiClient;
import com.competitive.clan.models.MemberProfile;
import com.competitive.clan.models.VerificationStartResponse;
import com.competitive.clan.models.VerificationStatus;

/**
 * Generates a link code, polls for it being claimed in Discord, and holds the resulting
 * session token + profile for the rest of the plugin to use.
 */
@Slf4j
public final class DefaultVerificationService implements VerificationService
{
	private final ClanApiClient api;
	private final SessionStore sessions;
	private final List<Consumer<MemberProfile>> listeners = new CopyOnWriteArrayList<>();
	private volatile MemberProfile currentProfile;

	public DefaultVerificationService(ClanApiClient api, SessionStore sessions)
	{
		this.api = api;
		this.sessions = sessions;
	}

	@Override
	public CompletionStage<VerificationStartResponse> generateLinkCode(String rsn)
	{
		return api.startVerification(rsn).thenApply(response ->
		{
			sessions.setPendingVerificationId(response.getVerificationId());
			return response;
		});
	}

	@Override
	public CompletionStage<VerificationStatus> refreshStatus()
	{
		CompletionStage<VerificationStatus> result = api.fetchVerificationStatus(
			sessions.getPendingVerificationId(), sessions.getSessionToken()
		).thenApply(status ->
		{
			if (hasText(status.getSessionToken()))
			{
				sessions.setSessionToken(status.getSessionToken());
				sessions.setPendingVerificationId("");
			}
			if (status.getProfile() != null)
			{
				updateProfile(status.getProfile());
			}
			return status;
		});

		result.whenComplete((status, error) ->
		{
			if (isUnauthorized(error))
			{
				clearSession();
			}
		});
		return result;
	}

	@Override
	public MemberProfile getCurrentProfile()
	{
		return currentProfile;
	}

	@Override
	public boolean isVerified()
	{
		return currentProfile != null && hasText(sessions.getSessionToken());
	}

	@Override
	public String getSessionToken()
	{
		return sessions.getSessionToken();
	}

	@Override
	public void addProfileListener(Consumer<MemberProfile> listener)
	{
		listeners.add(listener);
	}

	@Override
	public void clearSession()
	{
		sessions.clear();
		updateProfile(null);
	}

	private void updateProfile(MemberProfile profile)
	{
		currentProfile = profile;
		for (Consumer<MemberProfile> listener : listeners)
		{
			listener.accept(profile);
		}
	}

	private static boolean isUnauthorized(Throwable error)
	{
		Throwable current = error;
		while (current != null)
		{
			if (current instanceof ApiException && ((ApiException) current).getStatusCode() == 401)
			{
				return true;
			}
			current = current.getCause();
		}
		return false;
	}

	private static boolean hasText(String value)
	{
		return value != null && !value.trim().isEmpty();
	}
}

package com.competitive.clan.services;

public interface SessionStore
{
	String getSessionToken();
