package com.competitive.clan.services;

import java.util.function.Consumer;
import com.competitive.clan.models.ChatBridgeMessage;

/**
 * Two-way clan chat &lt;-&gt; Discord mirror: a persistent websocket with auto-reconnect and
 * keepalive, outbound messages batched and flushed periodically, and inbound messages
 * delivered via a callback the plugin registers to inject into clan chat.
 */
public interface ChatBridgeService
{
	void connect();

	void disconnect();

	boolean isConnected();

	/** Queues an outbound (clan chat -> Discord) message; actual sends are batched. */
	void enqueueOutbound(ChatBridgeMessage message);

	/** Registers the callback invoked for each inbound (Discord -> clan chat) message. */
	void onInboundMessage(Consumer<ChatBridgeMessage> listener);
}

package com.competitive.clan.services;

import java.util.concurrent.CompletionStage;
import java.util.function.Consumer;
import com.competitive.clan.models.MemberProfile;
import com.competitive.clan.models.VerificationStartResponse;
import com.competitive.clan.models.VerificationStatus;

public interface VerificationService
{
	/**
	 * Asks the bot for a fresh link code to show the player, e.g. "type /link ABC123 in Discord".
	 * The logged-in account name (RSN) is sent so the bot records exactly which account is being
	 * linked - this is authoritative (it comes straight from the game client) and handles alts,
	 * unlike a Discord nickname.
	 */
	CompletionStage<VerificationStartResponse> generateLinkCode(String rsn);

	/** Polls the bot to see if the pending code has been claimed yet. */
	CompletionStage<VerificationStatus> refreshStatus();

	MemberProfile getCurrentProfile();

	boolean isVerified();

	String getSessionToken();

	void addProfileListener(Consumer<MemberProfile> listener);

	void clearSession();
}

package com.competitive.clan.models;

import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;

/**
 * Returned by the bot when a player asks RuneLite to generate a new link code.
 * The player types {@code linkCode} into a Discord command (e.g. /link ABC123)
 * to associate their Discord account with this RuneLite session.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class VerificationStartResponse
{
	private String verificationId;
	private String linkCode;
	private String discordCommandHint;
	private long expiresAt;
}

package com.competitive.clan.models;

import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;

/**
 * A single message flowing across the two-way clan chat &lt;-&gt; Discord mirror.
 * "GAME" origin messages are outbound (clan chat -> Discord), "DISCORD" origin
 * messages are inbound (Discord -> clan chat).
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class ChatBridgeMessage
{
	public enum Origin { GAME, DISCORD, ANNOUNCEMENT, BINGO }

	private Origin origin;
	private String author;
	private String content;
	private String clanRank;
	private long timestamp;
	/** Only populated on outbound (GAME -> DISCORD) messages. */
	private String sessionToken;
	/**
	 * For GAME broadcasts (CLAN_MESSAGE): the classified type, e.g. "DROP", "QUEST", "DIARY".
	 * Null for regular typed clan chat. The bot uses it to decide which lines become rich embeds.
	 */
	private String broadcastType;
}

package com.competitive.clan.models;

import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;

/**
 * The clan member behind the currently linked Discord/RuneLite session.
 * Ranks are managed manually by clan staff in Discord, not by this plugin.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class MemberProfile
{
	private String rsn;
	private String discordId;
	private String discordUsername;
	private String clanRank;
	private boolean staff;
}

package com.competitive.clan.models;

import java.util.List;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * The current bingo board as served by the bot to the plugin (panel + overlay).
 * {@code active} is false when there's no running event.
 */
@Data
@NoArgsConstructor
public class BingoBoard
{
	private boolean active;
	private String name;
	private String mode;
	private String status;
	/** Board is size x size (2-9). */
	private int size;
	private List<Tile> tiles;
	private List<Standing> standings;
	/** Team rosters for this event (teams mode only; empty otherwise). */
	private List<Team> teams;
	/** The team the logged-in member is on for this event, or null if none. */
	private String yourTeam;

	@Data
	@NoArgsConstructor
	public static class Tile
	{
		private String desc;
		private int points;
		private boolean done;
		/** OSRS item id for the tile's icon, or 0 for non-item tiles. */
		private int itemId;
		/** Who (players or teams) has completed this tile. */
		private List<String> by;
	}

	@Data
	@NoArgsConstructor
	public static class Standing
	{
		private String name;
		private int points;
	}

	@Data
	@NoArgsConstructor
	public static class Team
	{
		private String name;
		/** In-game names of the members signed up to this team. */
		private List<String> members;
		private int points;
	}
}

package com.competitive.clan.models;

import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class VerificationStatus
{
	/** One of PENDING, VERIFIED, EXPIRED - kept as a plain String so the bot can evolve it without a plugin release. */
	private String state;
	private String sessionToken;
	private MemberProfile profile;
	private long expiresAt;

	public boolean isVerified()
	{
		return "VERIFIED".equalsIgnoreCase(state);
	}
}

