import com.competitive.clan.services.VerificationService;

/**
 * The plugin's single sidebar panel: verification status/flow at the top, and a live
 * "Events" section below (currently clan bingo, but built to hold other event types later).
 */
public class CompetitiveClanPanel extends PluginPanel
{
	private static final Color VERIFIED_COLOR = new Color(76, 175, 80);
	private static final Color PENDING_COLOR = new Color(230, 145, 56);
	private static final Color DONE_COLOR = new Color(76, 175, 80);

	// Board tile colours, mirroring the Discord board.
	private static final Color TILE_BG = new Color(42, 44, 51);
	private static final Color TILE_BORDER = new Color(58, 61, 69);
	private static final Color TILE_DONE_BG = new Color(31, 61, 36);
	private static final Color TILE_DONE_BORDER = new Color(63, 185, 80);
	private static final Color TILE_EMPTY_BG = new Color(36, 38, 44);
	private static final Color TILE_EMPTY_BORDER = new Color(49, 52, 60);

	private final VerificationService verificationService;
	private final Supplier<String> currentRsnSupplier;
	private final ItemManager itemManager;

	private final JLabel statusLabel = new JLabel();
	private final JLabel detailLabel = new JLabel();
	private final JLabel codeLabel = new JLabel();
	private final JLabel instructionsLabel = new JLabel();
	private final JButton generateButton = new JButton("Generate Link Code");
	private final JButton refreshButton = new JButton("Refresh Status");
	private final JPanel actionPanel = new JPanel();
	private final JPanel eventsPanel = new JPanel(new GridBagLayout());

	/** Section key -> expanded, so collapsing survives the panel rebuilding on new data. */
	private final Map<String, Boolean> sectionExpanded = new HashMap<>();

	private Runnable eventsRefresher = () -> { };

	public CompetitiveClanPanel(VerificationService verificationService, Supplier<String> currentRsnSupplier,
		ItemManager itemManager)
	{
		this.verificationService = verificationService;
		this.currentRsnSupplier = currentRsnSupplier;
		this.itemManager = itemManager;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));

		JPanel content = new JPanel(new GridBagLayout());
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		eventsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.anchor = GridBagConstraints.NORTH;

		c.gridy = 0;
		content.add(buildHeader(), c);
		c.gridy = 1;
		c.insets = new Insets(12, 0, 0, 0);
		content.add(buildStatusCard(), c);
		c.gridy = 2;
		c.insets = new Insets(10, 0, 0, 0);
		content.add(buildActionPanel(), c);
		c.gridy = 3;
		c.insets = new Insets(14, 0, 0, 0);
		content.add(eventsPanel, c);

		add(content, BorderLayout.NORTH);

		updateStatus(verificationService.getCurrentProfile());
		renderEvents(null);
		verificationService.addProfileListener(profile ->
			SwingUtilities.invokeLater(() -> updateStatus(profile)));
	}

	/** Wired by the plugin so the Refresh button also refreshes the events section. */
	public void setEventsRefresher(Runnable eventsRefresher)
	{
		this.eventsRefresher = eventsRefresher;
	}

	/** Called by the plugin when new event data arrives from the bot. */
	public void updateEvent(BingoBoard board)
	{
		renderEvents(board);
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel(new FlowLayout(FlowLayout.LEFT, 8, 0));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/competitive/clan/competitive_icon.png");
		if (icon != null)
		{
			header.add(new JLabel(new ImageIcon(icon)));
		}
		JLabel title = new JLabel("Competitive Clan");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		header.add(title);
		return header;
	}

	private JPanel buildStatusCard()
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		statusLabel.setFont(FontManager.getRunescapeBoldFont());
		statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		detailLabel.setForeground(Color.LIGHT_GRAY);
		detailLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		card.add(statusLabel);
		card.add(Box.createVerticalStrut(5));
		card.add(detailLabel);
		return card;
	}

	private JPanel buildActionPanel()
	{
		actionPanel.setLayout(new BoxLayout(actionPanel, BoxLayout.Y_AXIS));
		actionPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		codeLabel.setFont(FontManager.getRunescapeBoldFont().deriveFont(18f));
		codeLabel.setForeground(Color.WHITE);
		codeLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		instructionsLabel.setForeground(Color.LIGHT_GRAY);
		instructionsLabel.setAlignmentX(Component.CENTER_ALIGNMENT);

		generateButton.addActionListener(e -> onGenerateLinkCode());
		refreshButton.addActionListener(e -> onRefreshStatus());

		JPanel buttons = new JPanel(new GridLayout(0, 1, 0, 6));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		buttons.add(generateButton);
		buttons.add(refreshButton);

		actionPanel.add(codeLabel);
		actionPanel.add(Box.createVerticalStrut(2));
		actionPanel.add(instructionsLabel);
		actionPanel.add(Box.createVerticalStrut(8));
		actionPanel.add(buttons);
		return actionPanel;
	}

	private void renderEvents(BingoBoard board)
	{
		eventsPanel.removeAll();
		GridBagConstraints c = sectionConstraints();

		eventsPanel.add(buildSection("Events", "events", buildEventsBody(board)), c);

		// Teams get their own collapsible section, since a roster is worth scanning
		// independently of the board itself.
		List<BingoBoard.Team> teams = (board != null) ? board.getTeams() : null;
		if (board != null && board.isActive() && teams != null && !teams.isEmpty())
		{
			c.gridy++;
			c.insets = new Insets(8, 0, 0, 0);
			eventsPanel.add(buildSection("Teams", "teams", buildTeamsBody(board, teams)), c);
		}

		eventsPanel.revalidate();
		eventsPanel.repaint();
	}

	/** Everything event-specific: the event header, your team, the board, and standings. */
	private JPanel buildEventsBody(BingoBoard board)
	{
		JPanel body = newBody();
		GridBagConstraints c = sectionConstraints();

		if (board == null || !board.isActive())
		{
			JLabel none = new JLabel("No active events.");
			none.setForeground(Color.LIGHT_GRAY);
			body.add(none, c);
			return body;
		}

		body.add(new JLabel("<html><b>" + esc(board.getName()) + "</b><br><font color='#9a9a9a'>Bingo · "
			+ esc(board.getStatus()) + " · " + esc(board.getMode()) + "</font></html>"), c);

		// Tell the member which team they're on before anything else — it's the thing
		// they'll look for first once an event has teams.
		if (board.getYourTeam() != null && !board.getYourTeam().isEmpty())
		{
			c.gridy++;
			c.insets = new Insets(6, 0, 0, 0);
			body.add(new JLabel("<html>Your team: <b><font color='#3fb950'>"
				+ esc(board.getYourTeam()) + "</font></b></html>"), c);
		}
		else if (board.getTeams() != null && !board.getTeams().isEmpty())
		{
			c.gridy++;
			c.insets = new Insets(6, 0, 0, 0);
			body.add(new JLabel("<html><font color='#c9a227'>You're not on a team yet — "
				+ "sign up in Discord.</font></html>"), c);
		}

		c.gridy++;
		c.insets = new Insets(8, 0, 0, 0);
		body.add(buildBoardGrid(board), c);

		// Standings live inside Events — they only mean anything for the current event.
		List<BingoBoard.Standing> standings = board.getStandings();
		if (standings != null && !standings.isEmpty())
		{
			c.gridy++;
			c.insets = new Insets(8, 0, 0, 0);
			body.add(buildSection("Standings", "standings", buildStandingsBody(board, standings)), c);
		}

		return body;
	}

	private JPanel buildStandingsBody(BingoBoard board, List<BingoBoard.Standing> standings)
	{
		JPanel body = newBody();
		GridBagConstraints c = sectionConstraints();

		int rank = 0;
		for (BingoBoard.Standing s : standings)
		{
			rank++;
			boolean mine = s.getName() != null && s.getName().equals(board.getYourTeam());
			JLabel sl = new JLabel("<html>" + rank + ". " + (mine ? "<b><font color='#3fb950'>" : "")
				+ esc(s.getName()) + (mine ? "</font></b>" : "") + ": " + s.getPoints() + "</html>");
			sl.setForeground(Color.LIGHT_GRAY);
			body.add(sl, c);
			c.gridy++;
			c.insets = new Insets(2, 0, 0, 0);
		}
		return body;
	}

	private JPanel buildTeamsBody(BingoBoard board, List<BingoBoard.Team> teams)
	{
		JPanel body = newBody();
		GridBagConstraints c = sectionConstraints();

		for (BingoBoard.Team t : teams)
		{
			boolean mine = t.getName() != null && t.getName().equals(board.getYourTeam());
			List<String> members = t.getMembers();
			String roster = (members == null || members.isEmpty())
				? "no members yet"
				: String.join(", ", members);

			JLabel tl = new JLabel("<html><b>" + (mine ? "<font color='#3fb950'>" : "")
				+ esc(t.getName()) + (mine ? "</font>" : "") + "</b> (" + t.getPoints() + ")"
				+ "<br><font color='#9a9a9a'>" + esc(roster) + "</font></html>");
			tl.setForeground(Color.LIGHT_GRAY);
			body.add(tl, c);
			c.gridy++;
			c.insets = new Insets(6, 0, 0, 0);
		}
		return body;
	}

	private static GridBagConstraints sectionConstraints()
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = 0;
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.anchor = GridBagConstraints.NORTH;
		return c;
	}

	private static JPanel newBody()
	{
		JPanel body = new JPanel(new GridBagLayout());
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);
		body.setBorder(BorderFactory.createEmptyBorder(8, 4, 4, 4));
		return body;
	}

	/**
	 * A click-to-collapse section with a title bar. Expanded/collapsed state is keyed so it
	 * survives the panel being rebuilt when new event data arrives.
	 */
	private JPanel buildSection(String title, String key, JPanel body)
	{
		JPanel section = new JPanel(new BorderLayout());
		section.setBackground(ColorScheme.DARK_GRAY_COLOR);

		boolean expanded = sectionExpanded.getOrDefault(key, Boolean.TRUE);
		body.setVisible(expanded);

		JPanel bar = new JPanel(new BorderLayout(6, 0));
		bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bar.setBorder(BorderFactory.createEmptyBorder(5, 8, 5, 8));
		bar.setCursor(new Cursor(Cursor.HAND_CURSOR));

		// The arrow keeps the default UI font: the RuneScape font has no triangle glyphs.
		JLabel arrow = new JLabel(expanded ? "▼" : "►");
		arrow.setForeground(Color.LIGHT_GRAY);

		JLabel titleLabel = new JLabel(title);
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(Color.WHITE);

		bar.add(arrow, BorderLayout.WEST);
		bar.add(titleLabel, BorderLayout.CENTER);

		bar.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				boolean nowExpanded = !body.isVisible();
				body.setVisible(nowExpanded);
				sectionExpanded.put(key, nowExpanded);
				arrow.setText(nowExpanded ? "▼" : "►");
				section.revalidate();
				section.repaint();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				bar.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});

		section.add(bar, BorderLayout.NORTH);
		section.add(body, BorderLayout.CENTER);
		return section;
	}

	/** The board as a grid of icon tiles - green once completed, mirroring the Discord board. */
	private JPanel buildBoardGrid(BingoBoard board)
	{
		int size = Math.min(9, Math.max(2, board.getSize() > 0 ? board.getSize() : 5));
		List<BingoBoard.Tile> tiles = board.getTiles();

		final int gap = 3;
		JPanel grid = new JPanel(new GridLayout(size, size, gap, gap));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		int cell = Math.max(18, (PluginPanel.PANEL_WIDTH - 24 - (size - 1) * gap) / size);

		for (int i = 0; i < size * size; i++)
		{
			BingoBoard.Tile t = (tiles != null && i < tiles.size()) ? tiles.get(i) : null;

			JLabel cellLabel = new JLabel();
			cellLabel.setOpaque(true);
			cellLabel.setHorizontalAlignment(SwingConstants.CENTER);
			cellLabel.setPreferredSize(new Dimension(cell, cell));

			if (t == null)
			{
				cellLabel.setBackground(TILE_EMPTY_BG);
				cellLabel.setBorder(BorderFactory.createLineBorder(TILE_EMPTY_BORDER));
			}
			else
			{
				boolean done = t.isDone();
				cellLabel.setBackground(done ? TILE_DONE_BG : TILE_BG);
				cellLabel.setBorder(BorderFactory.createLineBorder(done ? TILE_DONE_BORDER : TILE_BORDER));

				String who = (done && t.getBy() != null && !t.getBy().isEmpty())
					? "<br><font color='#7ee787'>Done by " + esc(String.join(", ", t.getBy())) + "</font>" : "";
				cellLabel.setToolTipText("<html>" + esc(t.getDesc())
					+ (t.getPoints() > 1 ? " (" + t.getPoints() + "pt)" : "") + who + "</html>");

				if (t.getItemId() > 0 && itemManager != null)
				{
					setItemIcon(cellLabel, t.getItemId(), cell - 6);
				}
			}
			grid.add(cellLabel);
		}
		return grid;
	}

	/** Draws the item's own sprite from the game cache, scaled to fit the tile. */
	private void setItemIcon(JLabel label, int itemId, int maxSize)
	{
		try
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			Runnable apply = () -> SwingUtilities.invokeLater(() ->
			{
				double scale = Math.min((double) maxSize / image.getWidth(), (double) maxSize / image.getHeight());
				int w = Math.max(1, (int) Math.round(image.getWidth() * scale));
				int h = Math.max(1, (int) Math.round(image.getHeight() * scale));
				label.setIcon(new ImageIcon(image.getScaledInstance(w, h, Image.SCALE_SMOOTH)));
			});
			image.onLoaded(apply);
			apply.run(); // in case the sprite is already cached
		}
		catch (Exception ignored)
		{
			// No icon is fine - the tile still shows its colour and tooltip.
		}
	}

	private void onGenerateLinkCode()
	{
		String rsn = currentRsnSupplier.get();
		if (rsn == null || rsn.trim().isEmpty())
		{
			instructionsLabel.setForeground(PENDING_COLOR);
			instructionsLabel.setText("<html><center>Log into OSRS first, then try again.</center></html>");
			codeLabel.setText("");
			return;
		}
		generateButton.setEnabled(false);
		verificationService.generateLinkCode(rsn).whenComplete((response, error) ->
			SwingUtilities.invokeLater(() ->
			{
				generateButton.setEnabled(true);
				if (error != null)
				{
					instructionsLabel.setForeground(PENDING_COLOR);
					instructionsLabel.setText("<html><center>Couldn't reach the clan bot:<br>"
						+ esc(rootCauseMessage(error)) + "</center></html>");
					codeLabel.setText("");
					return;
				}
				showLinkCode(response);
			}));
	}

	private void onRefreshStatus()
	{
		verificationService.refreshStatus().whenComplete((status, error) ->
			SwingUtilities.invokeLater(() -> updateStatus(verificationService.getCurrentProfile())));
		eventsRefresher.run();
	}

	private void showLinkCode(VerificationStartResponse response)
	{
		codeLabel.setText(response.getLinkCode());
		instructionsLabel.setForeground(Color.LIGHT_GRAY);
		instructionsLabel.setText("<html><center>Run <b>" + esc(response.getDiscordCommandHint())
			+ "</b> in Discord,<br>then press Refresh Status.</center></html>");
	}

	private void updateStatus(MemberProfile profile)
	{
		boolean verified = profile != null;
		if (verified)
		{
			statusLabel.setForeground(VERIFIED_COLOR);
			statusLabel.setText("✔ Verified");
			detailLabel.setText("<html>" + esc(profile.getRsn())
				+ "<br><font color='#9a9a9a'>Discord: " + esc(profile.getDiscordUsername())
				+ "</font></html>");
			codeLabel.setText("");
			instructionsLabel.setText("");
			actionPanel.setVisible(false);
		}
		else
		{
			statusLabel.setForeground(PENDING_COLOR);
			statusLabel.setText("Not linked");
			detailLabel.setText("<html>Link your account to unlock the<br>Competitive clan tools.</html>");
			actionPanel.setVisible(true);
		}
		// Nothing past the login shows until verified: the events section is a members-only area.
		eventsPanel.setVisible(verified);
		revalidate();
		repaint();
	}

	private static String esc(String value)
	{
		if (value == null)
		{
			return "";
		}
		return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Unwrap a CompletableFuture's wrapped exception to the most useful message for display. */
	private static String rootCauseMessage(Throwable error)
	{
		Throwable current = error;
		while (current.getCause() != null && current.getCause() != current)
		{
			current = current.getCause();
		}
		String message = current.getMessage();
		return (message == null || message.isEmpty()) ? current.getClass().getSimpleName() : message;
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(PluginPanel.PANEL_WIDTH, super.getPreferredSize().height);
	}
}

package com.competitive.clan.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import com.competitive.clan.config.CompetitiveClanConfig;
import com.competitive.clan.models.BingoBoard;

/** On-screen widget showing the current bingo event's progress while playing. */
public class BingoOverlay extends OverlayPanel
{
	private volatile BingoBoard board;

	private final CompetitiveClanConfig config;

	@Inject
	public BingoOverlay(CompetitiveClanConfig config)
	{
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	public void setBoard(BingoBoard board)
	{
		this.board = board;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Checked per-frame rather than on startup, so toggling the setting takes effect at once.
		if (!config.showEventOverlay())
		{
			return null;
		}

		BingoBoard b = board;
		if (b == null || !b.isActive() || b.getTiles() == null)
		{
			return null; // nothing shown when there's no active event
		}

		int total = b.getTiles().size();
		int done = 0;
		for (BingoBoard.Tile t : b.getTiles())
		{
			if (t.isDone())
			{
				done++;
			}
		}

		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Bingo: " + b.getName())
			.color(new Color(155, 89, 182))
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Tiles")
			.right(done + "/" + total)
			.build());

		List<BingoBoard.Standing> standings = b.getStandings();
		if (standings != null && !standings.isEmpty())
		{
			BingoBoard.Standing top = standings.get(0);
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Leader")
				.right(top.getName() + " (" + top.getPoints() + ")")
				.build());

			// If this member is on a team, show where that team sits — that's what they care about.
			String mine = b.getYourTeam();
			if (mine != null && !mine.isEmpty())
			{
				for (int i = 0; i < standings.size(); i++)
				{
					if (mine.equals(standings.get(i).getName()))
					{
						panelComponent.getChildren().add(LineComponent.builder()
							.left("Your team")
							.right("#" + (i + 1) + " " + mine + " (" + standings.get(i).getPoints() + ")")
							.rightColor(new Color(63, 185, 80))
							.build());
						break;
					}
				}
			}
		}
		else if (b.getYourTeam() != null && !b.getYourTeam().isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Your team")
				.right(b.getYourTeam())
				.rightColor(new Color(63, 185, 80))
				.build());
		}

		return super.render(graphics);
	}
}

package com.competitive.clan.config;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

/**
 * Display settings only. The clan bot's address is built into the plugin, and outbound clan
 * chat and staff announcements are always on so the clan's own tools keep working - these
 * options only change what this member sees on their own screen.
 */
@ConfigGroup("competitiveClan")
public interface CompetitiveClanConfig extends Config
{
	@ConfigItem(
		keyName = "showEventOverlay",
		name = "Event overlay",
		description = "Show the on-screen event widget while an event is running.",
		position = 1
	)
	default boolean showEventOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showDiscordMessages",
		name = "Discord messages in game",
		description = "Show messages sent from the Discord clan chat channel in your game chat. "
			+ "Your own clan chat is still sent to Discord either way.",
		position = 2
	)
	default boolean showDiscordMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showEventAlerts",
		name = "Event tile alerts",
		description = "Show a chat message when an event tile is completed.",
		position = 3
	)
	default boolean showEventAlerts()
	{
		return true;
	}
}

