import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.OkHttpClient;
import com.competitive.clan.api.ClanApiClient;
import com.competitive.clan.api.RestClanApiClient;
import com.competitive.clan.config.CompetitiveClanConfig;
import com.competitive.clan.models.BingoBoard;
import com.competitive.clan.models.ChatBridgeMessage;
import com.competitive.clan.services.ChatBridgeService;
import com.competitive.clan.services.ChatClassifier;
import com.competitive.clan.services.DefaultChatBridgeService;
import com.competitive.clan.services.DefaultVerificationService;
import com.competitive.clan.services.RuneLiteSessionStore;
import com.competitive.clan.services.SessionStore;
import com.competitive.clan.services.VerificationService;
import com.competitive.clan.ui.BingoOverlay;
import com.competitive.clan.ui.CompetitiveClanPanel;

/**
 * Competitive clan tools:
 *  - Verification: links a RuneLite session to a Discord account via a bot-issued code.
 *    Acts as the plugin's login - the panel stays empty until it's done.
 *  - Clan chat mirror: two-way sync of clan chat with a Discord channel; clan broadcasts
 *    (drops, level-ups, quests, diaries, etc.) are forwarded so the bot can render them.
 *  - Events: the current clan event (bingo board, team rosters and standings) shown in the
 *    panel and an optional on-screen overlay, updating as tiles are completed.
 *
 * See LICENSE for third-party attributions.
 */
@Slf4j
@PluginDescriptor(
	name = "Competitive Clan Tools",
	description = "Discord verification, a two-way clan chat bridge, and a live clan event board",
	tags = {"competitive", "clan", "discord", "chat", "bridge", "events", "bingo", "teams"}
)
public class CompetitiveClanPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OkHttpClient httpClient;

	@Inject
	private Gson gson;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BingoOverlay bingoOverlay;

	@Inject
	private ItemManager itemManager;

	@Inject
	private CompetitiveClanConfig config;

	@Provides
	CompetitiveClanConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CompetitiveClanConfig.class);
	}

	private ClanApiClient apiClient;
	private VerificationService verificationService;
	private ChatBridgeService chatBridgeService;

	private NavigationButton navigationButton;
	private volatile CompetitiveClanPanel panel;
	private Timer autoRefreshTimer;

	/** Index of the Discord icon in the client's mod-icon table, or -1 if it couldn't be loaded. */
	private int discordIconSlot = -1;

	/** Dark-blue colour for the clan tag on relayed Discord lines (OSRS chat hex, no '#'). */
	private static final String CLAN_TAG_COLOR = "1c4587";

	/** Message-text colour, matched to OSRS clan chat's dark red (OSRS chat hex, no '#'). */
	private static final String MESSAGE_COLOR = "7f0000";

	/** Colour for staff announcements pushed in-game (OSRS chat hex, no '#'). */
	private static final String ANNOUNCEMENT_COLOR = "ffb000";

	/** Colour for bingo tile-complete alerts pushed in-game (OSRS chat hex, no '#'). */
	private static final String BINGO_COLOR = "b452cd";

	/** Text marker used before relayed Discord names if the Discord icon can't be loaded. */
	private static final String FALLBACK_MARKER = "[D]";

	@Override
	protected void startUp()
	{
		SessionStore sessionStore = new RuneLiteSessionStore(configManager);
		apiClient = new RestClanApiClient(httpClient, gson, "");
		verificationService = new DefaultVerificationService(apiClient, sessionStore);
		chatBridgeService = new DefaultChatBridgeService(httpClient, gson, apiClient.webSocketUrl(), verificationService);
		chatBridgeService.onInboundMessage(this::injectBridgedMessageIntoClanChat);

		SwingUtilities.invokeLater(() ->
		{
			BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/competitive/clan/competitive_icon.png");

			panel = new CompetitiveClanPanel(verificationService, this::currentPlayerName, itemManager);
			panel.setEventsRefresher(this::refreshBingoBoard);
			navigationButton = NavigationButton.builder()
				.tooltip("Competitive Clan Tools")
				.icon(icon)
				.panel(panel)
				.priority(5)
				.build();
			clientToolbar.addNavigation(navigationButton);
		});

		overlayManager.add(bingoOverlay);
		chatBridgeService.connect();

		// Load the Discord icon into the client's chat-icon table (must run on the client thread).
		clientThread.invoke(() ->
		{
			if (client.getModIcons() == null)
			{
				return false; // client not ready yet - RuneLite retries the invoke
			}
			loadDiscordIcon();
			return true;
		});

		startAutoRefresh();
	}

	@Override
	protected void shutDown()
	{
		if (autoRefreshTimer != null)
		{
			autoRefreshTimer.stop();
			autoRefreshTimer = null;
		}
		if (chatBridgeService != null)
		{
			chatBridgeService.disconnect();
		}
		overlayManager.remove(bingoOverlay);
		SwingUtilities.invokeLater(() ->
		{
			if (navigationButton != null)
			{
				clientToolbar.removeNavigation(navigationButton);
				navigationButton = null;
			}
			panel = null;
		});
	}

	private void startAutoRefresh()
	{
		autoRefreshTimer = new Timer(30_000, e ->
		{
			verificationService.refreshStatus();
			refreshBingoBoard();
		});
		autoRefreshTimer.setRepeats(true);
		autoRefreshTimer.start();
	}

	/** Fetch the current bingo board from the bot and update the panel + overlay. */
	private void refreshBingoBoard()
	{
		if (!verificationService.isVerified())
		{
			return;
		}
		apiClient.fetchBingoBoard(verificationService.getSessionToken()).whenComplete((board, error) ->
		{
			if (error != null || board == null)
			{
				return;
			}
			bingoOverlay.setBoard(board);
			SwingUtilities.invokeLater(() ->
			{
				if (panel != null)
				{
					panel.updateEvent(board);
				}
			});
		});
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		ChatMessageType type = chatMessage.getType();
		// Mirror everything that appears in clan chat: members' typed messages (CLAN_CHAT)
		// and system broadcasts like drops/level-ups (CLAN_MESSAGE). Drops aren't a special
		// case here - they're just clan-chat lines, so they flow to the same Discord channel.
		if (type == ChatMessageType.CLAN_CHAT || type == ChatMessageType.CLAN_MESSAGE)
		{
			mirrorClanLine(chatMessage);
		}
	}

	/** Outbound half of the two-way mirror: forward a clan-chat line (typed or broadcast) to Discord. */
	private void mirrorClanLine(ChatMessage chatMessage)
	{
		String content = ChatClassifier.sanitize(chatMessage.getMessage());
		if (content.isEmpty())
		{
			return;
		}

		// Skip local-only system hints that show in your own chat but aren't real clan content.
		if (content.contains("To talk in your clan") || content.contains("start each line of chat with"))
		{
			return;
		}

		// No anti-echo needed here: Discord messages are injected as GAMEMESSAGE (see below), and
		// this only mirrors CLAN_CHAT / CLAN_MESSAGE, so an injected line can never loop back.
		String author = ChatClassifier.sanitize(chatMessage.getName());
		String rank = author.isEmpty() ? null : resolveClanRank(author);

		// Tag system broadcasts (drops, quests, diaries, level-ups, etc.) with their classified
		// type so the bot can turn the right ones into rich embeds. Regular typed chat has no type.
		String broadcastType = chatMessage.getType() == ChatMessageType.CLAN_MESSAGE
			? ChatClassifier.classify(content).name()
			: null;

		ChatBridgeMessage bridged = new ChatBridgeMessage(
			ChatBridgeMessage.Origin.GAME, author, content, rank, System.currentTimeMillis(),
			verificationService.getSessionToken(), broadcastType
		);
		chatBridgeService.enqueueOutbound(bridged);
	}

	/** Inbound half of the mirror: injects a Discord message (or a staff announcement) into clan chat. */
	private void injectBridgedMessageIntoClanChat(ChatBridgeMessage message)
	{
		ChatBridgeMessage.Origin origin = message.getOrigin();
		boolean isAnnouncement = origin == ChatBridgeMessage.Origin.ANNOUNCEMENT;
		boolean isBingo = origin == ChatBridgeMessage.Origin.BINGO;

		// A tile just completed - pull the board straight away instead of waiting for the
		// next 30s poll, so the panel and overlay turn green immediately. This happens even
		// if the chat alert is switched off, so the board never goes stale.
		if (isBingo)
		{
			refreshBingoBoard();
			if (!config.showEventAlerts())
			{
				return;
			}
		}
		else if (!isAnnouncement && !config.showDiscordMessages())
		{
			// Staff announcements are deliberately not mutable; ordinary Discord chat is.
			return;
		}

		// Marker before the sender: the real Discord icon if we loaded it, else a text fallback.
		String marker = discordIconSlot >= 0 ? "<img=" + discordIconSlot + ">" : FALLBACK_MARKER + " ";
		String author = message.getAuthor();
		String content = message.getContent();

		clientThread.invoke(() ->
		{
			// Build the whole line ourselves and inject it as a plain GAME message, not a clan-chat
			// message. A clan-chat injection makes the game add its own "[clan] <rank-icon> name:"
			// scaffolding. A game message renders exactly the text we give it, and can't echo back
			// (we only mirror CLAN_CHAT/CLAN_MESSAGE, not GAMEMESSAGE).
			String line;
			if (isAnnouncement)
			{
				// Announcements stand out on their own line, no clan tag or icon.
				// (No emoji - the OSRS chat font can't render them, they show as "??".)
				line = "<col=" + ANNOUNCEMENT_COLOR + ">[Announcement] " + content + "</col>";
			}
			else if (isBingo)
			{
				line = "<col=" + BINGO_COLOR + ">[Bingo] " + content + "</col>";
			}
			else
			{
				ClanChannel clanChannel = client.getClanChannel();
				String clanName = (clanChannel != null && clanChannel.getName() != null) ? clanChannel.getName() : "Competitive";
				line = "<col=" + CLAN_TAG_COLOR + ">[" + clanName + "]</col> "
					+ marker + author + ": <col=" + MESSAGE_COLOR + ">" + content + "</col>";
			}
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", line, null);
		});
	}

	/** Loads discord_icon.png into the client's mod-icon table so it can be shown with &lt;img=slot&gt;. */
	private void loadDiscordIcon()
	{
		final IndexedSprite[] modIcons = client.getModIcons();
		if (discordIconSlot != -1 || modIcons == null)
		{
			return;
		}
		try
		{
			BufferedImage image = ImageUtil.loadImageResource(getClass(), "/com/competitive/clan/discord_icon.png");
			if (image == null)
			{
				log.warn("discord_icon.png not found; falling back to text marker");
				return;
			}
			IndexedSprite sprite = ImageUtil.getImageIndexedSprite(image, client);
			discordIconSlot = modIcons.length;
			IndexedSprite[] extended = Arrays.copyOf(modIcons, modIcons.length + 1);
			extended[extended.length - 1] = sprite;
			client.setModIcons(extended);
		}
		catch (Exception e)
		{
			log.warn("Could not load Discord icon, using text marker instead: {}", e.getMessage());
			discordIconSlot = -1;
		}
	}

	/** The logged-in account name, or null if not logged in yet. Sent to the bot when linking. */
	private String currentPlayerName()
	{
		Player local = client.getLocalPlayer();
		return local == null ? null : local.getName();
	}

	private String resolveClanRank(String playerName)
	{
		try
		{
			ClanChannel clanChannel = client.getClanChannel();
			ClanSettings clanSettings = client.getClanSettings();
			if (clanChannel == null || clanSettings == null)
			{
				return null;
			}
			ClanChannelMember member = clanChannel.findMember(playerName);
			if (member == null)
			{
				return null;
			}
			ClanRank rank = member.getRank();
			return clanSettings.titleForRank(rank).getName();
		}
		catch (Exception e)
		{
			log.debug("Could not resolve clan rank for {}: {}", playerName, e.getMessage());
			return null;
		}
	}
}

package com.competitive.clan.api;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;
import com.competitive.clan.models.BingoBoard;
import com.competitive.clan.models.VerificationStartResponse;
import com.competitive.clan.models.VerificationStatus;

/**
 * REST client for the Competitive clan Discord bot's API (the verification endpoints).
 */
@Slf4j
public final class RestClanApiClient implements ClanApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	/**
	 * The Competitive clan's bot address, baked in so members never have to enter a URL.
	 * This is not a secret (it's just an address); all real protection is on the bot side,
	 * which requires a valid session token for anything meaningful. Used whenever the
	 * bot URL passed in is blank.
	 */
	public static final String PRODUCTION_API_BASE_URL = "https://bot.competitive.run";

	private final OkHttpClient httpClient;
	private final Gson gson;
	private final HttpUrl baseUrl;
	private final ApiException configurationError;

	public RestClanApiClient(OkHttpClient httpClient, Gson gson, String baseUrl)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		HttpUrl parsed = HttpUrl.parse(normalizeBaseUrl(baseUrl));
		this.baseUrl = parsed == null ? HttpUrl.parse("http://invalid.local/") : parsed;
		this.configurationError = parsed == null
			? new ApiException("Competitive bot API URL is invalid; check the plugin's Bot API URL setting")
			: null;
	}

	@Override
	public CompletionStage<VerificationStartResponse> startVerification(String rsn)
	{
		return post(url("plugin", "verification", "start"), java.util.Collections.singletonMap("rsn", rsn), VerificationStartResponse.class);
	}

	@Override
	public CompletionStage<VerificationStatus> fetchVerificationStatus(String verificationId, String sessionToken)
	{
		HttpUrl target = baseUrl.newBuilder()
			.addPathSegment("plugin").addPathSegment("verification").addPathSegment("status")
			.addQueryParameter("verificationId", verificationId == null ? "" : verificationId)
			.build();
		return get(target, sessionToken, VerificationStatus.class);
	}

	@Override
	public CompletionStage<BingoBoard> fetchBingoBoard(String sessionToken)
	{
		return get(url("plugin", "bingo"), sessionToken, BingoBoard.class);
	}


	@Override
	public String webSocketUrl()
	{
		// OkHttp's HttpUrl only accepts http/https schemes (calling .scheme("ws") throws
		// "unexpected scheme: ws"). So build the address as http(s), then swap the scheme
		// on the string form - OkHttp's WebSocket layer accepts ws:// / wss:// and upgrades.
		String url = baseUrl.newBuilder().addPathSegment("ws").addPathSegment("chat").build().toString();
		if (url.startsWith("https://"))
		{
			return "wss://" + url.substring("https://".length());
		}
		if (url.startsWith("http://"))
		{
			return "ws://" + url.substring("http://".length());
		}
		return url;
	}

	private HttpUrl url(String... segments)
	{
		HttpUrl.Builder builder = baseUrl.newBuilder();
		for (String segment : segments)
		{
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	private <T> CompletionStage<T> get(HttpUrl url, String sessionToken, Class<T> responseType)
	{
		if (configurationError != null)
		{
			return failed(configurationError);
		}
		Request.Builder builder = new Request.Builder().url(url).get();
		if (sessionToken != null && !sessionToken.isEmpty())
		{
			builder.header("Authorization", "Bearer " + sessionToken);
		}
		return execute(builder.build(), responseType);
	}

	private <T> CompletionStage<T> post(HttpUrl url, Object body, Class<T> responseType)
	{
		if (configurationError != null)
		{
			return failed(configurationError);
		}
		RequestBody requestBody = RequestBody.create(JSON, gson.toJson(body));
		Request request = new Request.Builder().url(url).post(requestBody).build();
		return execute(request, responseType);
	}

	private <T> CompletionStage<T> execute(Request request, Class<T> responseType)
	{
		CompletableFuture<T> future = new CompletableFuture<>();
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.completeExceptionally(new ApiException("Network error: " + e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody responseBody = response.body())
				{
					String bodyText = responseBody == null ? "" : responseBody.string();
					if (!response.isSuccessful())
					{
						future.completeExceptionally(new ApiException("HTTP " + response.code() + ": " + bodyText, response.code()));
						return;
					}
					if (responseType == Void.class || bodyText.isEmpty())
					{
						future.complete(null);
						return;
					}
					future.complete(gson.fromJson(bodyText, responseType));
				}
				catch (Exception e)
				{
					future.completeExceptionally(new ApiException("Failed to parse response: " + e.getMessage()));
				}
				finally
				{
					response.close();
				}
			}
		});
		return future;
	}

	private static <T> CompletionStage<T> failed(ApiException error)
	{
		CompletableFuture<T> future = new CompletableFuture<>();
		future.completeExceptionally(error);
		return future;
	}

	private static String normalizeBaseUrl(String baseUrl)
	{
		String trimmed = baseUrl == null ? "" : baseUrl.trim();
		if (trimmed.isEmpty())
		{
			// No override entered - use the clan's bot address baked into the plugin.
			trimmed = PRODUCTION_API_BASE_URL;
		}
		return trimmed.endsWith("/") ? trimmed.substring(0, trimmed.length() - 1) : trimmed;
	}
}

package com.competitive.clan.api;

import java.util.concurrent.CompletionStage;
import com.competitive.clan.models.BingoBoard;
import com.competitive.clan.models.VerificationStartResponse;
import com.competitive.clan.models.VerificationStatus;

public interface ClanApiClient
{
	CompletionStage<VerificationStartResponse> startVerification(String rsn);

	CompletionStage<VerificationStatus> fetchVerificationStatus(String verificationId, String sessionToken);

	/** Current bingo board for the panel/overlay (requires a session token). */
	CompletionStage<BingoBoard> fetchBingoBoard(String sessionToken);

	/** Base HTTP(S) URL of the bot, with ws(s):// swapped in, for the chat bridge to connect to. */
	String webSocketUrl();
}

package com.competitive.clan.api;

public class ApiException extends RuntimeException
{
	private final int statusCode;

	public ApiException(String message)
	{
		this(message, -1);
	}

	public ApiException(String message, int statusCode)
	{
		super(message);
		this.statusCode = statusCode;
	}

	public int getStatusCode()
	{
		return statusCode;
	}
}
